enum LocalContentError: Swift.Error, Equatable, Hashable {

    
    
    case Sqlite(errMessage: String
    )
    case ForeignKeysUnavailable
    case WorkingCopyNotFound(id: WorkingCopyId
    )
    case InvalidDatabasePath(path: String
    )
    case RemotePostAlreadyHasWorkingCopy(postId: PostId
    )
    case PushedToAnotherRemotePost(editedPostId: PostId, pushedPostId: PostId
    )

    

    

    
}

#if compiler(>=6)
extension LocalContentError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLocalContentError: FfiConverterRustBuffer {
    typealias SwiftType = LocalContentError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LocalContentError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Sqlite(
            errMessage: try FfiConverterString.read(from: &buf)
            )
        case 2: return .ForeignKeysUnavailable
        case 3: return .WorkingCopyNotFound(
            id: try FfiConverterTypeWorkingCopyId.read(from: &buf)
            )
        case 4: return .InvalidDatabasePath(
            path: try FfiConverterString.read(from: &buf)
            )
        case 5: return .RemotePostAlreadyHasWorkingCopy(
            postId: try FfiConverterTypePostId.read(from: &buf)
            )
        case 6: return .PushedToAnotherRemotePost(
            editedPostId: try FfiConverterTypePostId.read(from: &buf), 
            pushedPostId: try FfiConverterTypePostId.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LocalContentError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Sqlite(errMessage):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(errMessage, into: &buf)
            
        
        case .ForeignKeysUnavailable:
            writeInt(&buf, Int32(2))
        
        
        case let .WorkingCopyNotFound(id):
            writeInt(&buf, Int32(3))
            FfiConverterTypeWorkingCopyId.write(id, into: &buf)
            
        
        case let .InvalidDatabasePath(path):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .RemotePostAlreadyHasWorkingCopy(postId):
            writeInt(&buf, Int32(5))
            FfiConverterTypePostId.write(postId, into: &buf)
            
        
        case let .PushedToAnotherRemotePost(editedPostId,pushedPostId):
            writeInt(&buf, Int32(6))
            FfiConverterTypePostId.write(editedPostId, into: &buf)
            FfiConverterTypePostId.write(pushedPostId, into: &buf)
            
        }
    }
}


